    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v in (1, 2):
                p[v] = (r, c)

    r, c = p[1]
    tr, tc = p[2]
    dr = 1 if tr > r else -1
    dc = 1 if tc > c else -1

    # Travel diagonally until one coordinate is one cell from the target,
    # then continue straight while keeping that coordinate fixed.
    while abs(tr - r) > 1 and abs(tc - c) > 1:
